def _loki_response(*, streams: list[dict]) -> bytes:
    """Build a Loki query_range API JSON response."""
    return json.dumps(
        {"status": "success", "data": {"resultType": "streams", "result": streams}}
    ).encode()


def _stream(*, session_id: str, prompt: str, host_name: str = "myhost") -> dict:
    """Build a single Loki stream entry with prompt in structured metadata labels."""
    return {
        "stream": {
            "service_name": "claude-code",
            "event_name": "user_prompt",
            "session_id": session_id,
            "host_name": host_name,
            "prompt": prompt,
        },
        "values": [["1718000000000000000", "claude_code.user_prompt"]],
    }


def _fake_urlopen_factory(streams: list[dict]):
    """Create a fake urlopen that returns the given streams for any request."""

    def fake_urlopen(req, timeout=None):
        mock = MagicMock()
        mock.read.return_value = _loki_response(streams=streams)
        mock.__enter__ = lambda s: s
        mock.__exit__ = MagicMock(return_value=False)
        return mock

    return fake_urlopen


class TestTruncate:
    def test_short_text_unchanged(self):
        assert _truncate("hello world", max_chars=200) == "hello world"

    def test_exact_limit_unchanged(self):
        text = "a" * 200
        assert _truncate(text, max_chars=200) == text

    def test_over_limit_truncated_with_ellipsis(self):
        text = "a" * 250
        result = _truncate(text, max_chars=200)
        assert len(result) == 200
        assert result.endswith("…")
        assert result[:-1] == "a" * 199

    def test_newlines_collapsed_to_spaces(self):
        text = "line one\nline two\nline three"
        assert _truncate(text, max_chars=200) == "line one line two line three"

    def test_multiple_whitespace_collapsed(self):
        text = "word   one    two\t\tthree"
        assert _truncate(text, max_chars=200) == "word one two three"

    def test_empty_string(self):
        assert _truncate("", max_chars=200) == ""

    def test_truncation_counts_ellipsis_in_limit(self):
        text = "a" * 10
        result = _truncate(text, max_chars=5)
        assert len(result) == 5
        assert result == "aaaa…"


